package com.csplusplus;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

import org.junit.jupiter.api.Test;

/**
 * Self-check tester for StringPractice.
 * Students: do not edit this file.
 *
 * Run tests from the Testing sidebar, or: mvn test
 */
public class StringPracticeTester {

    // --- printChars (2 checks) ---

    @Test
    void printChars_cat() {
        assertEquals("c\na\nt\n", captureOutput(() -> StringPractice.printChars("cat")));
    }

    @Test
    void printChars_Go() {
        assertEquals("G\no\n!\n", captureOutput(() -> StringPractice.printChars("Go!")));
    }

    // --- printReverse (2 checks) ---

    @Test
    void printReverse_cat() {
        assertEquals("t\na\nc\n", captureOutput(() -> StringPractice.printReverse("cat")));
    }

    @Test
    void printReverse_Java() {
        assertEquals("a\nv\na\nJ\n", captureOutput(() -> StringPractice.printReverse("Java")));
    }

    // --- countOccurrences (5 checks) ---

    @Test
    void countOccurrences_MISSISSIPPI_S() {
        assertEquals(4, StringPractice.countOccurrences("MISSISSIPPI", "S"));
    }

    @Test
    void countOccurrences_MISSISSIPPI_SS() {
        assertEquals(2, StringPractice.countOccurrences("MISSISSIPPI", "SS"));
    }

    @Test
    void countOccurrences_banana_ana() {
        assertEquals(2, StringPractice.countOccurrences("banana", "ana"));
    }

    @Test
    void countOccurrences_aaaa_aa_overlap() {
        assertEquals(3, StringPractice.countOccurrences("aaaa", "aa"));
    }

    @Test
    void countOccurrences_hi_hello() {
        assertEquals(0, StringPractice.countOccurrences("hi", "hello"));
    }

    // --- insertWord (3 checks) ---

    @Test
    void insertWord_morning_like() {
        assertEquals(
                "how like is like your like morning like going like",
                StringPractice.insertWord("how is your morning going", "like"));
    }

    @Test
    void insertWord_hi_there_um() {
        assertEquals("hi um there um", StringPractice.insertWord("hi there", "um"));
    }

    @Test
    void insertWord_hello_like() {
        assertEquals("hello like", StringPractice.insertWord("hello", "like"));
    }

    // --- Stretch (3 checks) ---

    @Test
    void isPalindrome_RADAR() {
        assertTrue(StringPractice.isPalindrome("RADAR"));
    }

    @Test
    void isPalindrome_DEBUG() {
        assertFalse(StringPractice.isPalindrome("DEBUG"));
    }

    @Test
    void removeAll_MISSISSIPPI_I() {
        assertEquals("MSSSSPP", StringPractice.removeAll("MISSISSIPPI", "I"));
    }

    private static String captureOutput(Runnable action) {
        PrintStream original = System.out;
        ByteArrayOutputStream capture = new ByteArrayOutputStream();
        System.setOut(new PrintStream(capture));
        try {
            action.run();
        } finally {
            System.setOut(original);
        }
        return capture.toString().replace("\r\n", "\n").replace("\r", "\n");
    }
}
